package art.niulai.android;

import android.app.*;
import android.content.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.util.*;
import org.json.*;

/** A usable native screen when an OEM disables or ships a broken WebView. */
final class CompatPanel extends ScrollView {
    private final MainActivity activity;private final LinearLayout content;
    private final NativeQuoteFeed feed;private NativeQuoteFeed probe;private QuoteGateway search;
    private JSONObject state;private NativeMarket.Quote quote;private boolean active,closed;
    private String motionError;private NativeBullView bullView;private final MarketMood moods=new MarketMood();
    private final Runnable moodTick=new Runnable(){public void run(){updateMotion();if(active)postDelayed(this,1000);}};
    private TextView name,code,price,delta,status,pnl,petToggle;private int ink,muted,paper,bg;
    CompatPanel(MainActivity a){
        super(a);activity=a;state=AppState.load(a);setFillViewport(true);content=new LinearLayout(a);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(20),dp(20),dp(20),dp(30));addView(content,new ScrollView.LayoutParams(-1,-2));
        feed=new NativeQuoteFeed((q,error)->{quote=q;showQuote(error);if(q!=null&&error==null){try{selected().put("name",q.name);}catch(Exception ignored){}persist();PetConfig.cache(a,NativeQuoteFeed.json(q));}});rebuild();
    }
    private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private JSONObject selected(){JSONArray list=state.optJSONArray("stocks");for(int i=0;i<list.length();i++){JSONObject s=list.optJSONObject(i);if(s.optString("code").equals(state.optString("selected")))return s;}return list.optJSONObject(0);}
    private TextView text(String value,int size,int color){TextView t=new TextView(activity);t.setText(value);t.setTextColor(color);t.setTextSize(size);t.setPadding(0,dp(5),0,dp(5));return t;}
    private TextView button(String label,Runnable action){TextView b=text(label,14,ink);b.setGravity(Gravity.CENTER);b.setMinHeight(dp(48));b.setBackground(shape(paper,12));b.setOnClickListener(v->action.run());return b;}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private LinearLayout card(){LinearLayout box=new LinearLayout(activity);box.setOrientation(1);box.setPadding(dp(18),dp(16),dp(18),dp(16));box.setBackground(shape(paper,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(15);content.addView(box,lp);return box;}
    private void rowButtons(String first,Runnable a,String second,Runnable b){LinearLayout row=new LinearLayout(activity);TextView left=button(first,a),right=button(second,b);LinearLayout.LayoutParams l=new LinearLayout.LayoutParams(0,dp(54),1),r=new LinearLayout.LayoutParams(0,dp(54),1);l.rightMargin=dp(5);r.leftMargin=dp(5);row.addView(left,l);row.addView(right,r);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(10);content.addView(row,p);}
    private void rebuild(){
        boolean dark=state.optString("theme").equals("dark")||(state.optString("theme").equals("system")&&(getResources().getConfiguration().uiMode&0x30)==0x20);
        ink=dark?0xffeeefe8:0xff282925;muted=dark?0xffa0a498:0xff74766f;paper=dark?0xff20231f:0xffffffff;bg=dark?0xff151714:0xfff5f4f0;setBackgroundColor(bg);activity.applyAppearance(dark);content.removeAllViews();
        LinearLayout brand=new LinearLayout(activity);brand.setGravity(Gravity.CENTER_VERTICAL);ImageView icon=new ImageView(activity);icon.setImageResource(getResources().getIdentifier("icon","drawable",activity.getPackageName()));brand.addView(icon,new LinearLayout.LayoutParams(dp(36),dp(36)));TextView title=text("  牛来盯盘",21,ink);title.setTypeface(null,1);brand.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView settings=button("设置",()->settings());settings.setTextColor(0xff3879ef);settings.setBackgroundColor(android.graphics.Color.TRANSPARENT);brand.addView(settings,new LinearLayout.LayoutParams(dp(48),dp(44)));content.addView(brand);
        LinearLayout desktop=card();desktop.setOrientation(0);desktop.setGravity(Gravity.CENTER_VERTICAL);LinearLayout labels=new LinearLayout(activity);labels.setOrientation(1);labels.addView(text("桌宠",15,ink));labels.addView(text("悬浮显示当前行情",11,muted));desktop.addView(labels,new LinearLayout.LayoutParams(0,-2,1));petToggle=button("开启桌宠",()->{if(PetService.petShowing)new AlertDialog.Builder(activity).setTitle("桌宠").setItems(new String[]{"返回桌面","关闭桌宠"},(d,i)->{if(i==0)activity.goHomeNative();else{activity.setOverlayEnabledNative("pet",false);postDelayed(()->updatePetState(),250);}}).show();else activity.startPetWithPermission();});petToggle.setTextColor(0xffffffff);petToggle.setBackground(shape(0xff3879ef,11));desktop.addView(petToggle,new LinearLayout.LayoutParams(dp(86),dp(40)));updatePetState();
        JSONObject stock=selected();LinearLayout quoteCard=card();name=text(stock.optString("name"),17,ink);name.setTypeface(null,1);quoteCard.addView(name);code=text(NativeMarket.display(stock.optString("code"))+" · "+NativeMarket.currency(stock.optString("code")),11,muted);quoteCard.addView(code);LinearLayout body=new LinearLayout(activity);body.setGravity(Gravity.CENTER_VERTICAL);LinearLayout values=new LinearLayout(activity);values.setOrientation(1);price=text("—",32,0xffe34952);price.setTypeface(null,1);price.setSingleLine(true);price.setEllipsize(android.text.TextUtils.TruncateAt.END);delta=text("—",13,muted);values.addView(price);values.addView(delta);body.addView(values,new LinearLayout.LayoutParams(0,-2,1));
        NativeBullView bull=new NativeBullView(activity);bullView=bull;bull.setContentDescription("摸摸牛来");body.addView(bull,new LinearLayout.LayoutParams(dp(120),dp(138)));bull.setOnClickListener(v->{if(state.optBoolean("haptic",true))AndroidCompat.vibrate(activity);Toast.makeText(activity,"牛来",Toast.LENGTH_SHORT).show();});quoteCard.addView(body);status=text("正在连接行情…",10,muted);quoteCard.addView(status);TextView refresh=button("刷新行情",()->feed.refresh());refresh.setTextColor(0xff3879ef);refresh.setMinHeight(dp(36));quoteCard.addView(refresh);
        LinearLayout holding=card();LinearLayout head=new LinearLayout(activity);head.setGravity(Gravity.CENTER_VERTICAL);head.addView(text("当前持仓",14,ink),new LinearLayout.LayoutParams(0,-2,1));TextView edit=button("编辑",()->editPosition());edit.setTextColor(0xff3879ef);head.addView(edit,new LinearLayout.LayoutParams(dp(44),dp(36)));holding.addView(head);pnl=text("尚未设置持仓",12,muted);holding.addView(pnl);
        rowButtons("自选",()->watchlist(),"添加股票",()->searchDialog());rowButtons("桌面卡片",()->activity.pinWidgetNative(),"系统与权限",()->activity.supportSettingsNative("app"));rowButtons("检查更新",()->activity.checkUpdatesNative(),"更新通知设置",()->activity.updatePermission());TextView full=button("切换到完整界面",()->{PetConfig.prefs(activity).edit().putBoolean("force_native",false).apply();activity.recreate();});full.setTextColor(muted);full.setBackgroundColor(android.graphics.Color.TRANSPARENT);content.addView(full,new LinearLayout.LayoutParams(-1,dp(48)));TextView footer=text("牛来盯盘 1.4.0 · 兼容模式",10,muted);footer.setGravity(Gravity.CENTER);content.addView(footer);showQuote(null);sync();
    }
    void refreshAppearance(){rebuild();}
    void updatePetState(){if(petToggle!=null)petToggle.setText(PetService.petShowing?"管理桌宠":"开启桌宠");}
    private void updateMotion(){if(bullView==null)return;String symbol=selected().optString("code");boolean valid=quote!=null&&quote.code.equals(symbol);bullView.state(moods.update(symbol,valid?quote.price:0,valid?quote.pct:0,valid?quote.received:0,valid,motionError!=null,System.currentTimeMillis(),state.optInt("interval",10)));bullView.configure(active,state.optBoolean("motion",true));}
    private void showQuote(String error){motionError=error;updateMotion();JSONObject stock=selected();code.setText(NativeMarket.display(stock.optString("code"))+" · "+NativeMarket.currency(stock.optString("code")));name.setText(quote!=null?quote.name:stock.optString("name"));price.setText(quote==null?"—":String.format(Locale.US,"%,.2f",quote.price));price.setTextColor(quote!=null&&quote.pct<0?0xff278565:0xffcc483f);delta.setText(quote==null?"—":String.format(Locale.US,"%+.3f    %+.2f%%",quote.change,quote.pct));delta.setTextColor(quote!=null&&quote.pct<0?0xff119b7b:0xffe34952);
        status.setText(error!=null?error:quote==null?"正在连接行情…":"获取于 "+new java.text.SimpleDateFormat("HH:mm:ss",Locale.CHINA).format(new Date(quote.received))+(quote.time.isEmpty()?" · 源未提供时间":" · 源时间 "+quote.time));
        double cost=stock.optDouble("cost",0),shares=stock.optDouble("shares",0);boolean hide=activity.coverMode()&&state.optBoolean("private",true);pnl.setText(hide?"持仓金额已隐藏":quote!=null&&cost>0&&shares>0?String.format(Locale.US,"今日 %+.2f · 累计 %+.2f %s",(quote.price-quote.dayPrevClose)*shares,(quote.price-cost)*shares,NativeMarket.currency(stock.optString("code"))):"尚未设置持仓");
    }
    private void persist(){try{FeatureOptions.copy(AppState.load(activity),state);}catch(Exception ignored){}AppState.save(activity,state.toString());sync();}
    private void sync(){try{JSONObject config=new JSONObject(state.toString());JSONObject stock=selected();config.put("symbol",stock.getString("code"));config.put("name",stock.optString("name"));if(!state.optBoolean("private",true)){config.put("cost",stock.optDouble("cost",0));config.put("shares",stock.optDouble("shares",0));}PetConfig.configure(activity,config.toString());if(active&&PetService.running)activity.startService(new Intent(activity,PetService.class).setAction(PetService.CONFIG));feed.configure(stock.getString("code"),state.optInt("interval",10));StackWidgetProvider.refreshAll(activity);}catch(Exception ignored){}}
    private void choose(int index){try{state.put("selected",state.getJSONArray("stocks").getJSONObject(index).getString("code"));quote=null;persist();showQuote(null);feed.refresh();}catch(Exception ignored){}}
    private void watchlist(){JSONArray list=state.optJSONArray("stocks");String[] labels=new String[list.length()];for(int i=0;i<labels.length;i++){JSONObject s=list.optJSONObject(i);labels[i]=s.optString("name")+" · "+NativeMarket.display(s.optString("code"));}
        new AlertDialog.Builder(activity).setTitle("我的自选").setItems(labels,(d,index)->choose(index)).setNeutralButton("移出当前",(d,w)->{JSONObject s=selected();if(list.length()<=1||s.optDouble("shares",0)>0){toast("至少保留一只；有持仓时请先清除持仓");return;}JSONArray next=new JSONArray();for(int i=0;i<list.length();i++)if(!list.optJSONObject(i).optString("code").equals(s.optString("code")))next.put(list.optJSONObject(i));try{state.put("stocks",next);state.put("selected",next.getJSONObject(0).getString("code"));quote=null;persist();showQuote(null);}catch(Exception ignored){}}).setNegativeButton("返回",null).show();
    }
    private EditText input(String hint,int type){EditText e=new EditText(activity);e.setHint(hint);e.setInputType(type);e.setSingleLine(true);e.setPadding(dp(14),dp(12),dp(14),dp(12));return e;}
    private void searchDialog(){EditText input=input("名称或代码，如 茅台 / 00700 / AAPL",InputType.TYPE_CLASS_TEXT);new AlertDialog.Builder(activity).setTitle("添加股票").setView(input).setPositiveButton("查找",(d,w)->{
        String value=input.getText().toString().trim();String direct=NativeMarket.normalize(value);if(direct!=null){validateAndAdd(direct);return;}if(value.isEmpty()||value.length()>40){toast("请输入名称或代码");return;}
        if(search!=null)search.close();search=new QuoteGateway((id,body,error)->post(()->{if(closed||!active)return;List<NativeMarket.Stock> results=error==null?NativeMarket.suggestions(body):Collections.emptyList();if(results.isEmpty()){toast("未找到股票，请检查网络或使用完整代码");return;}String[] labels=new String[results.size()];for(int i=0;i<labels.length;i++)labels[i]=results.get(i).name+" · "+NativeMarket.display(results.get(i).code);new AlertDialog.Builder(activity).setTitle("搜索结果").setItems(labels,(dd,index)->validateAndAdd(results.get(index).code)).setNegativeButton("返回",null).show();}));search.request("1","search",value);
    }).setNegativeButton("返回",null).show();}
    private void validateAndAdd(String code){JSONArray list=state.optJSONArray("stocks");for(int i=0;i<list.length();i++)if(list.optJSONObject(i).optString("code").equals(code)){choose(i);return;}if(list.length()>=20){toast("自选已满 20 只");return;}toast("正在验证股票行情…");if(probe!=null)probe.close();probe=new NativeQuoteFeed((q,error)->{if(probe!=null){probe.close();probe=null;}if(closed||!active)return;if(q==null||error!=null){toast("暂无有效行情，未添加");return;}try{JSONObject s=new JSONObject();s.put("code",q.code);s.put("name",q.name);s.put("cost",0);s.put("shares",0);list.put(s);state.put("selected",q.code);quote=q;persist();showQuote(null);}catch(Exception ignored){}});probe.configure(code,30);probe.setActive(true);}
    private void editPosition(){JSONObject stock=selected();LinearLayout form=new LinearLayout(activity);form.setOrientation(1);EditText cost=input("每股成本",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL),shares=input("持有股数",InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);if(stock.optDouble("cost",0)>0)cost.setText(stock.optString("cost"));if(stock.optDouble("shares",0)>0)shares.setText(stock.optString("shares"));form.addView(cost);form.addView(shares);
        AlertDialog d=new AlertDialog.Builder(activity).setTitle(stock.optString("name")+" · "+NativeMarket.currency(stock.optString("code"))).setView(form).setPositiveButton("保存",null).setNeutralButton("清除",(dd,w)->{try{stock.put("cost",0);stock.put("shares",0);persist();showQuote(null);}catch(Exception ignored){}}).setNegativeButton("返回",null).create();d.setOnShowListener(v->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(vv->{try{double c=Double.parseDouble(cost.getText().toString()),s=Double.parseDouble(shares.getText().toString());if(!(c>0&&c<=1e9&&s>0&&s<=1e12))throw new NumberFormatException();stock.put("cost",c);stock.put("shares",s);persist();showQuote(null);d.dismiss();}catch(Exception e){toast("请输入有效成本和股数");}}));d.show();
    }
    private void settings(){String[] labels={"点击桌宠播放声音","点击轻震","动画","桌面隐藏持仓金额"};String[] keys={"sound","haptic","motion","private"};boolean[] values=new boolean[4];for(int i=0;i<4;i++)values[i]=state.optBoolean(keys[i],i!=0);
        new AlertDialog.Builder(activity).setTitle("设置").setMultiChoiceItems(labels,values,(d,i,checked)->{try{state.put(keys[i],checked);persist();}catch(Exception ignored){}}).setPositiveButton("完成",(d,w)->rebuild()).setNeutralButton("刷新频率",(d,w)->new AlertDialog.Builder(activity).setItems(new String[]{"5 秒","10 秒","30 秒"},(dd,i)->{try{state.put("interval",new int[]{5,10,30}[i]);persist();}catch(Exception ignored){}}).show()).setNegativeButton("外观",(d,w)->new AlertDialog.Builder(activity).setItems(new String[]{"跟随系统","浅色","深色"},(dd,i)->{try{state.put("theme",new String[]{"system","light","dark"}[i]);persist();rebuild();}catch(Exception ignored){}}).show()).show();
    }
    private void toast(String message){Toast.makeText(activity,message,Toast.LENGTH_SHORT).show();}
    void resume(){active=true;sync();feed.setActive(true);updatePetState();removeCallbacks(moodTick);post(moodTick);}void pause(){active=false;removeCallbacks(moodTick);if(bullView!=null)bullView.configure(false,false);feed.setActive(false);if(probe!=null){probe.close();probe=null;}if(search!=null){search.close();search=null;}}
    void close(){closed=true;pause();feed.close();}
}


